from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class CalibrationsScenario(BaseScenario):
    name = 'calibrations'
    description = 'Model calibration tools'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='list_calibrations_default', tool='list_calibrations', params={}, expected={'is_array': True, 'error': False, 'min_length': 1}, description='List calibrations returns fixture data'), TestCase(name='list_calibrations_limited', tool='list_calibrations', params={'limit': 10}, expected={'is_array': True, 'error': False}, description='List calibrations with custom limit'), TestCase(name='get_calibration_default_model', tool='get_calibration', params={'model': 'default'}, expected={'json_valid': True, 'contains_keys': ['model_name', 'overall_bias', 'sample_size']}, description='Get calibration for default model'), TestCase(name='get_calibration_not_found', tool='get_calibration', params={'model': 'nonexistent_model_xyz'}, expected={'contains_keys': ['error']}, description='Get calibration for non-existent model returns error'), TestCase(name='get_calibration_with_error_type', tool='get_calibration', params={'model': 'default', 'error_type': 'timeout'}, expected={'json_valid': True, 'contains_keys': ['model_name']}, description='Get calibration for specific error type'), TestCase(name='get_calibration_trend_default', tool='get_calibration_trend', params={'model': 'default'}, expected={'json_valid': True, 'error': False, 'contains_keys': ['model_name']}, description='Get calibration trend for default model'), TestCase(name='get_calibration_summary', tool='get_calibration_summary', params={}, expected={'json_valid': True, 'error': False}, description='Get cross-model calibration summary'), TestCase(name='export_calibration_default', tool='export_calibration', params={'model': 'default'}, expected={'json_valid': True, 'error': False}, description='Export calibration data for default model')]